import numpy as np
import xarray as xr
from satpy.readers.eps_l1b import EPSAVHRRFile
from enum import IntEnum

class MockValueList(IntEnum):
    reflectance = 1
    brightness_temperature = 2
    radiance = 3

class MockEPSAVHRRFile(EPSAVHRRFile):
    def __init__(self):
        self.platform_name = "Metop-C"
        self.sensor_name = "avhrr-3"
        self.sections = {}
        # This is what's currently in the code
        self.units = {"reflectance": "%", "brightness_temperature": "K"}

    def _get_data_array(self, key):
        return xr.DataArray(np.zeros((10, 10)), dims=["y", "x"])

    def get_dataset(self, key, info):
        dataset = self._get_data_array(key)
        dataset.attrs["platform_name"] = self.platform_name
        dataset.attrs["sensor"] = self.sensor_name
        if "calibration" in key:
            dataset.attrs["units"] = self.units[key["calibration"]]
        return dataset

key = {"calibration": MockValueList.radiance}
reader = MockEPSAVHRRFile()

try:
    reader.get_dataset(key, {})
    print("Success!")
except KeyError as e:
    print(f"Caught expected KeyError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    import traceback
    traceback.print_exc()
